values ('p-poulet-fermier', 'poulet-fermier-entier', 'cat-volailles', '{"fr":"Poulet fermier entier","ar":"دجاج بلدي كامل"}'::jsonb, '{"fr":"Élevé 90 jours en plein air, environ 1,7 kg","ar":"مرباة 90 يوماً في الهواء الطلق، حوالي 1.7 كغ"}'::jsonb, '{"fr":"Notre poulet fermier grandit lentement, dehors, nourri au grain. Chair ferme et goûteuse, peau dorée à la cuisson. Livré entier, vidé et prêt à rôtir. Le prix est ajusté au poids réel à la pesée.","ar":"ينمو دجاجنا البلدي ببطء في الهواء الطلق ويتغذى على الحبوب. لحم متماسك ولذيذ وجلد ذهبي عند الطهي. يُسلَّم كاملاً ومنظفاً وجاهزاً للشوي. يُعدَّل السعر حسب الوزن الحقيقي عند الوزن."}'::jsonb, array['/images/products/poulet-entier.jpg']::text[], '{"mode":"per_kg_estimated","price_per_kg":14.9,"est_weight_kg":1.7,"min_weight_kg":1.4,"max_weight_kg":2.1,"max_qty":10}'::jsonb, null, array['fermier', 'best']::text[], 'en_stock', true, 1, '{"fr":"Se conserve 3 jours au réfrigérateur. Sortez-le 30 min avant de le cuire.","ar":"يُحفظ 3 أيام في الثلاجة. أخرجه قبل الطهي بـ30 دقيقة."}'::jsonb)
