-- Recettes
insert into public.recipes (id, slug, title, intro, image, duration_min, servings, difficulty, ingredients, steps, product_slugs)
values ('r-poulet-roti', 'poulet-roti-aux-herbes', '{"fr":"Poulet rôti aux herbes du Cap Bon","ar":"دجاج مشوي بأعشاب الوطن القبلي"}'::jsonb, '{"fr":"Le dimanche à la maison : un poulet fermier, du thym, du citron, et le four qui fait le reste.","ar":"الأحد في البيت: دجاج بلدي، زعتر، ليمون، والفرن يقوم بالباقي."}'::jsonb, '/images/recipes/recette-poulet-roti.jpg', 90, 4, 1, '{"fr":["1 poulet fermier entier","1 citron","4 gousses d’ail","Thym et romarin","3 c. à s. d’huile d’olive","Sel, poivre","1 kg de pommes de terre"],"ar":["دجاجة بلدية كاملة","ليمونة","4 فصوص ثوم","زعتر وإكليل الجبل","3 ملاعق كبيرة زيت زيتون","ملح وفلفل","1 كغ بطاطا"]}'::jsonb, '{"fr":["Préchauffez le four à 200 °C. Sortez le poulet 30 minutes avant.","Frottez-le d’huile d’olive, de sel et de poivre. Glissez le citron coupé et l’ail dans le ventre.","Posez-le sur les pommes de terre coupées en quartiers, parsemez d’herbes.","Enfournez 1 h 15. Arrosez toutes les 20 minutes avec le jus.","Laissez reposer 10 minutes sous un torchon avant de découper."],"ar":["سخّن الفرن على 200 درجة. أخرج الدجاجة قبل 30 دقيقة.","ادهنها بزيت الزيتون والملح والفلفل. ضع الليمون المقطّع والثوم داخلها.","ضعها فوق البطاطا المقطّعة أرباعاً وانثر الأعشاب.","اطهِها ساعة وربع. اسقها بالمرق كل 20 دقيقة.","اتركها ترتاح 10 دقائق تحت منشفة قبل التقطيع."]}'::jsonb, array['poulet-fermier-entier']::text[])
on conflict (id) do update set slug = excluded.slug, title = excluded.title, intro = excluded.intro, image = excluded.image, duration_min = excluded.duration_min, servings = excluded.servings, difficulty = excluded.difficulty, ingredients = excluded.ingredients, steps = excluded.steps, product_slugs = excluded.product_slugs;
insert into public.recipes (id, slug, title, intro, image, duration_min, servings, difficulty, ingredients, steps, product_slugs)
values ('r-tajine', 'tajine-de-poulet-aux-olives', '{"fr":"Tajine de poulet aux olives et au citron confit","ar":"طاجين دجاج بالزيتون والليمون المصبّر"}'::jsonb, '{"fr":"Des cuisses qui mijotent doucement, des olives, un citron confit : le plat qui parfume toute la maison.","ar":"أفخاذ تُطهى على نار هادئة، زيتون وليمون مصبّر: الطبق الذي يعطّر البيت كله."}'::jsonb, '/images/recipes/recette-tajine.jpg', 75, 4, 2, '{"fr":["1 kg de cuisses de poulet","2 oignons","1 citron confit","150 g d’olives vertes","1 c. à c. de curcuma","1 c. à c. de gingembre","Coriandre fraîche","Huile d’olive"],"ar":["1 كغ أفخاذ دجاج","بصلتان","ليمونة مصبّرة","150 غ زيتون أخضر","ملعقة صغيرة كركم","ملعقة صغيرة زنجبيل","كزبرة طازجة","زيت زيتون"]}'::jsonb, '{"fr":["Faites dorer les cuisses dans l’huile d’olive, réservez.","Faites fondre les oignons émincés avec les épices.","Remettez le poulet, couvrez d’eau à mi-hauteur, laissez mijoter 45 minutes à couvert.","Ajoutez les olives et le citron confit en morceaux, poursuivez 10 minutes.","Parsemez de coriandre et servez avec du pain ou de la semoule."],"ar":["حمّر الأفخاذ في زيت الزيتون ثم ضعها جانباً.","اطهُ البصل المقطّع مع التوابل حتى يذبل.","أعد الدجاج وغطّه بالماء إلى النصف واتركه يغلي 45 دقيقة مغطّى.","أضف الزيتون وقطع الليمون المصبّر واطهُ 10 دقائق أخرى.","انثر الكزبرة وقدّمه مع الخبز أو السميد."]}'::jsonb, array['cuisses-de-poulet']::text[])
on conflict (id) do update set slug = excluded.slug, title = excluded.title, intro = excluded.intro, image = excluded.image, duration_min = excluded.duration_min, servings = excluded.servings, difficulty = excluded.difficulty, ingredients = excluded.ingredients, steps = excluded.steps, product_slugs = excluded.product_slugs;
insert into public.recipes (id, slug, title, intro, image, duration_min, servings, difficulty, ingredients, steps, product_slugs)
values ('r-brochettes', 'brochettes-grillees-harissa', '{"fr":"Brochettes grillées, harissa et citron","ar":"أسياخ مشوية بالهريسة والليمون"}'::jsonb, '{"fr":"La braise du soir, les brochettes déjà marinées, une salade mechouia à côté.","ar":"جمر المساء، أسياخ متبّلة مسبقاً، وسلطة مشوية إلى جانبها."}'::jsonb, '/images/recipes/recette-brochettes.jpg', 25, 4, 1, '{"fr":["1 kg de brochettes de poulet marinées","1 c. à s. de harissa","1 citron","Pain tabouna","Salade mechouia"],"ar":["1 كغ أسياخ دجاج متبّلة","ملعقة كبيرة هريسة","ليمونة","خبز طابونة","سلطة مشوية"]}'::jsonb, '{"fr":["Sortez les brochettes 20 minutes avant la cuisson.","Sur une braise bien grise, grillez 4 minutes par face.","Mélangez la harissa avec le jus de citron, badigeonnez en fin de cuisson.","Servez dans le pain tabouna avec la mechouia."],"ar":["أخرج الأسياخ قبل الطهي بـ20 دقيقة.","على جمر رمادي جيد، اشوِ 4 دقائق لكل جهة.","اخلط الهريسة مع عصير الليمون وادهن بها في نهاية الطهي.","قدّمها في خبز الطابونة مع السلطة المشوية."]}'::jsonb, array['brochettes-de-poulet-marinees']::text[])
on conflict (id) do update set slug = excluded.slug, title = excluded.title, intro = excluded.intro, image = excluded.image, duration_min = excluded.duration_min, servings = excluded.servings, difficulty = excluded.difficulty, ingredients = excluded.ingredients, steps = excluded.steps, product_slugs = excluded.product_slugs;
insert into public.recipes (id, slug, title, intro, image, duration_min, servings, difficulty, ingredients, steps, product_slugs)
values ('r-ojja', 'ojja-aux-merguez', '{"fr":"Ojja aux merguez et aux œufs fermiers","ar":"عجّة بالمرقاز والبيض البلدي"}'::jsonb, '{"fr":"Le plat du soir en 20 minutes : tomates, merguez, poivrons, et les œufs qui prennent dessus.","ar":"طبق المساء في 20 دقيقة: طماطم، مرقاز، فلفل، والبيض يستوي فوقها."}'::jsonb, '/images/recipes/recette-omelette.jpg', 20, 2, 1, '{"fr":["4 œufs fermiers","250 g de merguez de volaille","3 tomates","1 poivron vert","2 gousses d’ail","1 c. à s. de concentré de tomate","Harissa, carvi, sel"],"ar":["4 بيضات بلدية","250 غ مرقاز دواجن","3 طماطم","فلفلة خضراء","فصان ثوم","ملعقة كبيرة معجون طماطم","هريسة، كروية، ملح"]}'::jsonb, '{"fr":["Faites revenir les merguez coupées en tronçons, réservez.","Dans la même poêle, faites fondre l’ail, le poivron et le concentré, puis les tomates en dés. Laissez réduire 10 minutes.","Remettez les merguez, cassez les œufs par-dessus, couvrez 3 minutes.","Servez aussitôt avec du pain."],"ar":["حمّر المرقاز المقطّع ثم ضعه جانباً.","في نفس المقلاة اطهُ الثوم والفلفل والمعجون ثم الطماطم المقطّعة. اتركها تتكاثف 10 دقائق.","أعد المرقاز واكسر البيض فوقه وغطّه 3 دقائق.","قدّمها فوراً مع الخبز."]}'::jsonb, array['oeufs-fermiers-x6', 'merguez-de-volaille']::text[])
